INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn is spun to 40s Ne. Approximately how many yards of this yarn weigh exactly one pound?', '["33,600 yards","8,400 yards","40 yards","16,800 yards"]'::jsonb, '33,600 yards', 'Total yards per pound = count × 840 yards (hank length). 40 × 840 = 33,600 yards.', 2, '{"yarn-count-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A yarn is spun to 24s Ne. Approximately how many yards of this yarn weigh exactly one pound?', '["20,160 yards","840 yards","24 yards","10,080 yards"]'::jsonb, '20,160 yards', 'Total yards per pound = count × 840 yards. 24 × 840 = 20,160 yards.', 1, '{"yarn-count-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Two 30s Ne single yarns are twisted together (plied) to make a 2-ply yarn. What is the approximate resultant count?', '["15s Ne","30s Ne","60s Ne","10s Ne"]'::jsonb, '15s Ne', 'Resultant ply count ≈ single count ÷ number of plies for Ne (indirect system): 30 ÷ 2 = 15s Ne.', 2, '{"ply-count-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Three 18s Ne single yarns are twisted together to make a 3-ply yarn. What is the approximate resultant count?', '["6s Ne","18s Ne","54s Ne","9s Ne"]'::jsonb, '6s Ne', 'Resultant ply count ≈ single count ÷ number of plies: 18 ÷ 3 = 6s Ne.', 2, '{"ply-count-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A draw frame applies a draft of 8 to an input sliver of hank 0.10 Ne. What is the approximate output sliver hank?', '["0.80 Ne","0.0125 Ne","8.10 Ne","0.10 Ne"]'::jsonb, '0.80 Ne', 'Output hank = input hank × draft, since drafting proportionally thins the strand (raising the count number). 0.10 × 8 = 0.80 Ne.', 2, '{"draft-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A draw frame applies a draft of 5 to an input sliver of hank 0.15 Ne. What is the approximate output sliver hank?', '["0.75 Ne","0.03 Ne","5.15 Ne","0.15 Ne"]'::jsonb, '0.75 Ne', 'Output hank = input hank × draft. 0.15 × 5 = 0.75 Ne.', 2, '{"draft-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A ring frame spindle rotates at 12,000 rpm and the desired twist is 24 turns per inch. Approximately what yarn delivery speed (inches per minute) does this imply?', '["500 inches/min","12,024 inches/min","288,000 inches/min","24 inches/min"]'::jsonb, '500 inches/min', 'Delivery speed = spindle rpm ÷ TPI, since each inch of yarn needs TPI spindle rotations. 12,000 ÷ 24 = 500 inches/min.', 2, '{"twist-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A ring frame spindle rotates at 18,000 rpm and the desired twist is 30 turns per inch. Approximately what yarn delivery speed (inches per minute) does this imply?', '["600 inches/min","18,030 inches/min","540,000 inches/min","30 inches/min"]'::jsonb, '600 inches/min', 'Delivery speed = spindle rpm ÷ TPI. 18,000 ÷ 30 = 600 inches/min.', 2, '{"twist-calculation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn count is given as 20s Ne. Using the approximate conversion Tex ≈ 590.5 / Ne, what is its approximate Tex value?', '["≈ 29.5 Tex","≈ 590.5 Tex","≈ 20 Tex","≈ 11,810 Tex"]'::jsonb, '≈ 29.5 Tex', 'Tex ≈ 590.5 / Ne = 590.5 / 20 ≈ 29.5 Tex.', 2, '{"tex-ne-conversion"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn count is given as 40s Ne. Using the approximate conversion Tex ≈ 590.5 / Ne, what is its approximate Tex value?', '["≈ 14.8 Tex","≈ 590.5 Tex","≈ 40 Tex","≈ 23,620 Tex"]'::jsonb, '≈ 14.8 Tex', 'Tex ≈ 590.5 / Ne = 590.5 / 40 ≈ 14.8 Tex.', 2, '{"tex-ne-conversion"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A cotton/polyester blend yarn is specified as 60% cotton and 40% polyester by weight, for a total yarn weight of 1000 kg in a production lot. How many kg of cotton fiber are needed?', '["600 kg","400 kg","500 kg","1000 kg"]'::jsonb, '600 kg', 'Cotton weight = 60% of total = 0.60 × 1000 kg = 600 kg.', 1, '{"blend-ratio-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'A cotton/polyester blend yarn is specified as 65% polyester and 35% cotton by weight, for a total yarn weight of 2000 kg in a production lot. How many kg of polyester fiber are needed?', '["1300 kg","700 kg","1000 kg","2000 kg"]'::jsonb, '1300 kg', 'Polyester weight = 65% of total = 0.65 × 2000 kg = 1300 kg.', 1, '{"blend-ratio-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A cotton sample has a bone-dry (oven-dry) weight of 100 g and, after conditioning, weighs 108.5 g. What is its moisture regain percentage?', '["8.5%","108.5%","91.5%","1.085%"]'::jsonb, '8.5%', 'Moisture regain % = (moisture weight / oven-dry weight) × 100 = (8.5 / 100) × 100 = 8.5%.', 2, '{"moisture-regain-calc"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A cotton sample has a bone-dry (oven-dry) weight of 200 g and, after conditioning, weighs 214 g. What is its moisture regain percentage?', '["7%","14%","93%","0.07%"]'::jsonb, '7%', 'Moisture regain % = (moisture weight / oven-dry weight) × 100 = (14 / 200) × 100 = 7%.', 2, '{"moisture-regain-calc"}'::text[]);
